CREATE OR REPLACE FUNCTION editing_protocol_fence() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE protocol text; paused boolean; BEGIN SELECT p.protocol,p.paused INTO STRICT protocol,paused FROM editing_protocol p WHERE singleton FOR SHARE; IF current_setting('airdesign.history_protocol',true) IS DISTINCT FROM 'paragraph-body-v3' THEN IF paused THEN RAISE EXCEPTION 'editing-paused' USING ERRCODE='55000'; END IF; IF protocol='paragraph-body-v3' THEN RAISE EXCEPTION 'editing-protocol-mismatch' USING ERRCODE='55000'; END IF; END IF; RETURN NULL; END $$
